    "difficulty": "medium",
    "question_text": "Triangle $DEF$ is similar to triangle $ABC$, with each side length of $DEF$ being 3 times the corresponding side length of $ABC$. If the area of triangle $ABC$ is 12$ square units, what is the area of triangle $DEF$?",
    "question_type": "multiple_choice",
    "options": [
      "A) 36",
      "B) 108",
      "C) 15",
      "D) 216"
    ],
    "correct_answer": "B",
    "explanation": "When linear dimensions of similar polygons scale by a factor of $k$, their areas scale by $k^2$. Here $k = 3$, so the area scales by $k^2 = 3^2 = 9$. Thus, the area of $DEF$ is 12 \\times 9 = 108$ square units."
