    "topic": "Central Ideas and Details",
    "difficulty": "medium",
    "context_passage": "Cephalopods such as the common octopus (Octopus vulgaris) possess a decentralized nervous system wherein approximately two-thirds of their neurons are distributed among their eight flexible arms. Rather than requiring centralized cortical execution for every micro-movement, each arm can independently sample chemical tastes, coordinate suckers, and execute reflex actions autonomously. This distributed sensory architecture enables the octopus to forage under multiple rocky crevices simultaneously while the central brain monitors surroundings for predators. [Research Record #1]",
    "question_text": "Which choice best states the central idea of the text?",
