    "context_passage": "Environmental scientists tested four building insulation retrofits on municipal structures to evaluate thermal performance and energy reductions:\n- Baseline uninsulated exterior masonry: Heat loss: 1.8 W/m²K; Annual heating cost: $42,000\n- Fiberglass batt insulation (R-13): Heat loss: 0.44 W/m²K; Annual heating cost: $28,000\n- Blown cellulose insulation (R-20): Heat loss: 0.28 W/m²K; Annual heating cost: $21,000\n- Vacuum insulation panels (VIP) with thermal breaks: Heat loss: 0.12 W/m²K; Annual heating cost: $14,000\nThe engineers concluded that vacuum insulation panels provide superior thermal resistance, reducing heating expenditures by two-thirds relative to baseline. [Building Evaluation #14]",
    "question_text": "Which choice best uses data from the study to support the engineers' conclusion?",
    "question_type": "multiple_choice",
    "options": [
      "A) Fiberglass batt insulation reduced heat loss more effectively than blown cellulose.",
      "B) Vacuum insulation panels recorded the lowest heat loss (0.12 W/m²K) and reduced annual heating costs from $42,000 to $14,000.",
      "C) Baseline uninsulated masonry incurred lower heating costs than blown cellulose.",
      "D) Annual heating costs were identical between fiberglass batts and vacuum insulation panels."
    ],
    "correct_answer": "B",
    "explanation": "The data explicitly demonstrates that vacuum insulation panels achieved the lowest heat loss (0.12) and slashed costs from $42,000 to $14,000 (a two-thirds reduction)."
